import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String want = sc.next();

        System.out.println(want.equals("{f1}"));
        System.out.println(want.equals("{item}"));
    }
}
